package projectSoftware.app;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;

class MessageUtilsTest {
    @Test void testGetMessage() {
        assertEquals("Hello      World!", MessageUtils.getMessage());
    }
    @Test
    public void testFound(){
        // Girilen eleman array list var bu fonksiyon true olmalı
        ArrayList <Integer> array = new ArrayList <> (Arrays.asList(1,2,3,4));
        assertTrue(MessageUtils.search(array,4));
    }
    @Test
    public void testNotFound(){
        // Girilen eleman array list yok bu fonksiyon false olmalı
        ArrayList <Integer> array = new ArrayList <> (Arrays.asList(1,2,3,4));
        assertFalse(MessageUtils.search(array,5));
    }
    @Test
    public void testEmptyArray(){
        // Girilen eleman array list boş  bu fonksiyon arama sonucunda false olmalı
        ArrayList <Integer> array = new ArrayList <> (Arrays.asList());
        assertFalse(MessageUtils.search(array,1));
    }
    @Test
    public void testNull(){
        //  array list hiç oluşturulmamış ise bu bloğa girmeli
        assertFalse(MessageUtils.search(null,1));

        //denemek amaçalı olmadığı halde true döndürüp test cevabını bakalım
        //assertTrue(MessageUtils.search(null,1));

    }
}
